};

const Suite = enum { none, aes_128_gcm_sha256, chacha20_poly1305_sha256 };

fn suiteName(s: Suite) []const u8 {
    return switch (s) {
        .none => "none",
        .aes_128_gcm_sha256 => "TLS_AES_128_GCM_SHA256",
        .chacha20_poly1305_sha256 => "TLS_CHACHA20_POLY1305_SHA256",
    };
}

